88:     //////////////////////// INTERNAL: SEASON OF PLENTY ////////////////////////
89: 
90:     /**
91:      * @dev Gas optimization: An account can call `{SiloFacet:claimPlenty}` even
92:      * if `s.accts[account].sop.plenty == 0`. This would emit a ClaimPlenty event
93:      * with an amount of 0.
94:      */
95:     function _claimPlenty(address account, address well, LibTransfer.To toMode) internal {
96:         uint256 plenty = s.accts[account].sop.perWellPlenty[well].plenty;
97:         if (plenty > 0 && LibWell.isWell(well)) {
98:             IERC20[] memory tokens = IWell(well).tokens();
99:             IERC20 sopToken = tokens[0] != C.bean() ? tokens[0] : tokens[1];
100:             LibTransfer.sendToken(sopToken, plenty, LibTractor._user(), toMode);
101:             s.accts[account].sop.perWellPlenty[well].plenty = 0;
102: 
103:             // reduce from Beanstalk's total stored plenty for this well
104:             s.sys.sop.plentyPerSopToken[address(sopToken)] -= plenty;
105: 
106:             emit ClaimPlenty(account, address(sopToken), plenty);
107:         }
108:     }
