112:     /**
113:      * @notice Claim Grown Stalk for `account`.
114:      * @dev See {Silo-_mow}.
115:      */
116:     function mow(
117:         address account,
118:         address token
119:     ) external payable fundsSafu noNetFlow noSupplyChange {
120:         LibSilo._mow(account, token);
121:     }
122: 
123:     //function to mow multiple tokens given an address
124:     function mowMultiple(
125:         address account,
126:         address[] calldata tokens
127:     ) external payable fundsSafu noNetFlow noSupplyChange {
128:         for (uint256 i; i < tokens.length; ++i) {
129:             LibSilo._mow(account, tokens[i]);
130:         }
131:     }
