133:     /**
134:      * @notice Claim Earned Beans and their associated Stalk and Plantable Seeds for
135:      * user.
136:      *
137:      * The Stalk associated with Earned Beans is commonly called "Earned Stalk".
138:      * Earned Stalk DOES contribute towards the Farmer's Stalk when earned beans is issued.
139:      *
140:      * The Seeds associated with Earned Beans are commonly called "Plantable
141:      * Seeds". The word "Plantable" is used to highlight that these Seeds aren't
142:      * yet earning the Farmer new Stalk. In other words, Seeds do NOT automatically
143:      * compound; they must first be Planted with {plant}.
144:      *
145:      * In practice, when Seeds are Planted, all Earned Beans are Deposited in
146:      * the current Season.
147:      */
148:     function plant()
149:         external
150:         payable
151:         fundsSafu
152:         noNetFlow
153:         noSupplyChange
154:         returns (uint256 beans, int96 stem)
155:     {
156:         return _plant(LibTractor._user());
157:     }
